// ─── File: src/main/java/com/bank/core/Account.java ───
package com.bank.core;

import java.math.BigDecimal;
import java.util.*;

public class Account {
    private final String accountId;
    private final BigDecimal balance;

    public Account(String accountId, BigDecimal balance) {
        // BOUNDARY: enforce invariants → interior never checks these for null.
        this.accountId = Objects.requireNonNull(accountId, "accountId required");
        this.balance   = Objects.requireNonNull(balance, "balance required");
    }

    // Return EMPTY, never null → callers never guard.
    public List<String> recentTransfers() {
        return List.of(); // no transfers yet → empty, not null
    }

    // Optional for a possibly-absent single result (return value only).
    public Optional<String> nickname() {
        return Optional.empty();
    }

    public String getAccountId() { return accountId; }
    public BigDecimal getBalance() { return balance; }
}
```

