// ─── File: src/main/java/com/bank/core/NullHandlingDemo.java ───
package com.bank.core;

import java.math.BigDecimal;
import java.util.logging.*;

public class NullHandlingDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    private static Customer lookupCustomer(String id) {
        // Instead of returning null for unknown → return the Null Object.
        return "SAV2001".equals(id) ? new RegisteredCustomer("Rajesh Kumar") : new GuestCustomer();
    }

    public static void main(String[] args) {
        // 1) Boundary validation.
        try {
            new Account(null, new BigDecimal("1"));
        } catch (NullPointerException e) {
            log.log(Level.SEVERE, "Boundary rejected null accountId", e);
        }

        Account rajesh = new Account("SAV2001", new BigDecimal("1000000.00"));

        // 2) Return empty, not null → no guard needed.
        int count = rajesh.recentTransfers().size();
        log.info(() -> "recentTransfers size (empty, no NPE) → " + count);

        // Optional return for absence.
        String nick = rajesh.nickname().orElse("N/A");
        log.info(() -> "nickname → " + nick);

        // 3) Null Object → no null check at call site.
        Customer known = lookupCustomer("SAV2001");
        Customer unknown = lookupCustomer("ZZZ9999");
        log.info(() -> "known → " + known.displayName() + " registered=" + known.isRegistered());
        log.info(() -> "unknown → " + unknown.displayName() + " registered=" + unknown.isRegistered());
    }
}
